# Bangla versions of English items (cross-lingual retrieval and answering).
BANGLA = {
    "b01": ("q01", "পেঁপের রিংস্পট ভাইরাস কোন পোকা ছড়ায়?"),
    "b02": ("q14", "মাটির সোলারাইজেশন কাজ করাতে কত সপ্তাহ পলিথিন দিয়ে ঢেকে রাখতে হয়?"),
    "b03": ("q16", "টবের মাটি বা সয়েললেস কালচারে কি কম সময়ের সোলারাইজেশন যথেষ্ট?"),
    "b04": ("q19", "অতিরিক্ত নাইট্রোজেন সার দিলে গ্রিনহাউসের গাছে বট্রাইটিস ব্লাইট রোগ কেমন হয়?"),
    "b05": ("q24", "মাটির আর্দ্রতা কেমন থাকলে গাছ সবচেয়ে সহজে পুষ্টি পায়?"),
    "b06": ("q25", "জলাবদ্ধ মাটিতে ম্যাঙ্গানিজের কী হতে পারে?"),
    "b07": ("q12", "আলুর লেট ব্লাইট রোগ কোন জীবাণুর কারণে হয়?"),
    "b08": ("q05", "পটাশিয়াম গাছের বৃদ্ধিতে কী কাজ করে?"),
    "b09": ("q28", "অতিরিক্ত সেচ দিলে কি গাছের রোগ বাড়তে পারে?"),
    "b10": ("q23", "আমের পরাগায়ন কোন পোকা করে?"),
}

# Questions the book cannot answer; the verifier checks that the key terms never occur in it.
UNANSWERABLE = [
    ("u02", "How many ml of neem oil per litre should I spray on rooftop chilli plants?", ["neem oil"]),
    ("u03", "Which ChhadKrishi shop product is best for my balcony tomatoes?", ["ChhadKrishi"]),
    ("u04", "What is the best month to plant tomatoes on a rooftop in Chattogram?", ["Chattogram", "Chittagong"]),
    ("u05", "How often should I water a money plant (Epipremnum) on my balcony?", ["Epipremnum", "money plant"]),
    ("u06", "What dose of Nativo fungicide should I use on my roses?", ["Nativo"]),
    ("u08", "How do I care for a snake plant (Sansevieria) indoors?", ["Sansevieria", "snake plant"]),
    ("u09", "What is the weather forecast for Rajshahi this week?", ["Rajshahi"]),
    ("u10", "Who won the 2022 FIFA World Cup?", ["FIFA"]),
    ("u11", "How many grams of DAP fertilizer does a potted aloe vera need each month?", ["aloe vera"]),
    ("u12", "ছাদে কাঁচা মরিচের টবে কত গ্রাম সরিষার খৈল দেব?", ["mustard cake"]),
    ("u13", "What subsidy does the Dhaka city corporation give for rooftop gardens?", ["city corporation"]),
]


def main() -> None:
    items, by_id = [], {}
    for id_, question, pages, quotes, must in ANSWERABLE:
        item = {"id": id_, "type": "answerable", "lang": "en", "question": question, "gold_pages": pages, "gold_quotes": quotes, "must_include": must}
        items.append(item)
        by_id[id_] = item
    for id_, (source, question) in BANGLA.items():
        s = by_id[source]
        items.append({"id": id_, "type": "answerable", "lang": "bn", "question": question, "gold_pages": s["gold_pages"], "gold_quotes": s["gold_quotes"], "must_include": [], "translation_of": source})
    for id_, question, absent in UNANSWERABLE:
        lang = "bn" if any("ঀ" <= ch <= "৿" for ch in question) else "en"
        items.append({"id": id_, "type": "unanswerable", "lang": lang, "question": question, "absent_terms": absent})
    out = Path(__file__).with_name("questions.jsonl")
    out.write_text("\n".join(json.dumps(i, ensure_ascii=False) for i in items) + "\n", encoding="utf-8")
    print(f"{len(items)} items → {out}")


if __name__ == "__main__":
    main()
